Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='recordeddecisions', at=datetime(2026, 10, 3, 0, 0, 0), actor='assistant', title='Designs and plans are recorded decisions, items of a store of their own; specs and laws stay files', body="The RECORDED DECISIONS (2026-10-03, ARCHITECTURE §10.8; `suzatary_core::decisions`) are a prodrome of their own: designs and plans as items of `decisions/`, keyed by decision, a discrete statement, an inflationary life and a grow-only supersedes set, ordered by supersession alone; specs and laws stay files. Not a `decision` todo, which is a choice awaiting the owner's tap.", rationale='Decided 2026-10-03 (ARCHITECTURE §10.8).', supersedes=()))